import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/yfr4')
from lib import *
FVG="Portions de fruits et légumes"
def fv(n): return f"{FVG}§{FVG} par portion : {n}"
FRZ="Instructions de congélation : "
recs=[
R(7793516,"Biryani au poulet","Oubliez les plats à emporter et optez pour un dîner savoureux, complet et riche en goût, mais léger en calories.","4","421 g",
["2 c. à café d'huile de tournesol","1 gros oignon, haché","300 g de blanc de poulet sans peau, coupé en morceaux","1 poivron rouge, haché","1 carotte, coupée en dés","8 champignons, émincés","1 aubergine, coupée en cubes","1 c. à soupe de pâte de curry (douce, moyenne ou forte)","1 c. à soupe de raisins secs blonds","250 g de riz basmati complet, rincé à l'eau froide","800 ml d'eau bouillante","100 g de petits pois surgelés, décongelés","1 poignée de coriandre fraîche, hachée","1 c. à soupe d'huile d'olive"],
["Versez l'huile de tournesol dans une casserole avec l'oignon, faites cuire 2 minutes, puis ajoutez le poulet et remuez encore 3 à 4 minutes.","Ajoutez le poivron rouge, la carotte, les champignons et l'aubergine, et poursuivez la cuisson 5 minutes en remuant régulièrement.","Incorporez la pâte de curry et les raisins secs et mélangez bien.","Ajoutez ensuite le riz aux légumes en mélangeant bien. Versez alors l'eau bouillante et mélangez à nouveau. Portez à ébullition, puis réduisez le feu au minimum. Couvrez et laissez cuire 11 minutes.","Éteignez le feu et laissez reposer 5 minutes sans retirer le couvercle.","Ajoutez les petits pois, la coriandre et l'huile d'olive au riz. Mélangez bien et servez."],
["Pour une version végétarienne, ajoutez un poivron supplémentaire, une courgette hachée et une boîte de pois chiches.","Vous pouvez aussi utiliser de la dinde, des crevettes ou du saumon à la place du poulet.","Vous pouvez aussi remplacer une partie de la viande par des haricots, riches en protéines et en fibres, et moins chers.","Si vous n'avez pas d'aubergine, ajoutez simplement des champignons et des carottes en plus.","La coriandre n'est pas indispensable : le plat sera tout aussi savoureux sans.","Si vous n'avez pas de riz sous la main, pourquoi ne pas essayer le quinoa ou le couscous complet.","Peut être congelé une fois cuit. Décongelez ensuite au réfrigérateur et réchauffez jusqu'à ce que le plat soit bien chaud à cœur.",fv(2)]),
R(7798440,"Houmous léger","Une version saine de ce délicieux dip, idéal avec des crudités, des gressins ou du pain pita.","6","50 g",
["1 boîte de 400 g de pois chiches, égouttés et rincés","1 gousse d'ail","jus d'1 citron","1 c. à café de piment de Cayenne","4 c. à soupe de yaourt nature","poivre noir fraîchement moulu","Pour servir§pain pita réchauffé, coupé en morceaux"],
["Mettez tous les ingrédients du houmous dans un robot de cuisine ou un mixeur et mixez jusqu'à obtenir une texture presque lisse et homogène.","Versez dans un bol de service et servez avec le pain pita réchauffé."],
["Cette recette est une excellente source de fibres, essentielles à une bonne santé digestive.","Si vous n'avez pas de pois chiches en boîte, vous pouvez utiliser des pois chiches secs, en suivant les instructions de l'emballage pour les préparer et les cuire.","Pour plus de saveur, ajoutez 1 c. à café de tahini, ou 1 c. à café de paprika fumé ou de cumin. Pour plus de peps, ajoutez le zeste râpé d'un citron.",FRZ+"congelez par portions, puis décongelez au réfrigérateur ou au micro-ondes, en prenant soin de remuer régulièrement.",fv(0)]),
R(7798713,"Salade de bœuf croustillant, sauce au raifort","Une salade facile qui utilise des ingrédients simples avec une touche originale.","4","217 g",
["2 c. à soupe de yaourt grec à 0 % de matières grasses","2 c. à café de sauce au raifort","3 laitues « little gem », grossièrement coupées","120 g de tomates cerises, coupées en petits quartiers","100 g de concombre, en bâtonnets","1 c. à café de fécule de maïs","1 c. à café de paprika","1 paquet (300 g) de lanières de bœuf pour sauté","1 spray d'huile d'olive","1 c. à soupe de graines de sésame","4 oignons nouveaux, coupés en tronçons de 3 cm","1 poivron rouge, émincé finement","Jus d'un demi-citron"],
["Mélangez le yaourt et la sauce au raifort et réservez.","Dans un saladier ou sur un plat, mélangez la laitue, la tomate et le concombre et réservez.","Mélangez la fécule de maïs et le paprika et enrobez-en bien les lanières de bœuf.","Vaporisez de l'huile dans une poêle et placez-la sur feu moyen. Lorsqu'elle est chaude, ajoutez le bœuf et faites cuire 2 à 3 minutes en remuant régulièrement. Saupoudrez de graines de sésame, puis retirez de la poêle et réservez.","Ajoutez les oignons et le poivron rouge dans la poêle, faites cuire 3 minutes, puis arrosez de jus de citron. Mélangez bien et versez à la cuillère sur la salade, ajoutez le bœuf et des noisettes de sauce au yaourt. Servez immédiatement."],
["Cette recette fonctionne bien avec des lanières de poulet, de porc ou de dinde. Excellente avec du riz ou des nouilles de riz.","Vous pouvez utiliser de la moutarde de Dijon ou à l'ancienne à la place du raifort.","Pour une version végétarienne, utilisez un mélange de tofu et de pleurotes à la place du bœuf.",fv(1)]),
R(7800433,"Poisson au four sur lit de chou-fleur et lentilles","Simple, savoureux, sain et presque pas de vaisselle. Un dîner complet en un seul plat, c'est gagnant ! Cette recette a été sélectionnée en partenariat avec Slimming World.","4","564 g",
["1 chou-fleur, feuilles et tronc retirés, coupé en bouquets","Spray de cuisson basses calories","2 boîtes de 400 g de lentilles vertes, brunes ou noires, égouttées et rincées","200 g de haricots verts, équeutés et coupés en deux","250 ml de bouillon de volaille à teneur réduite en sel, préparé avec ½ cube de bouillon","4 filets de poisson blanc sans peau ni arêtes (nous avons utilisé du cabillaud), bien séchés","4 oignons nouveaux, finement émincés","1 gousse d'ail, écrasée","10 g de persil plat frais, haché","1 citron, coupé en quartiers, pour servir"],
["Préchauffez le four à 200 °C (chaleur tournante 180 °C, th. 6). Étalez les bouquets de chou-fleur en une seule couche dans un plat de cuisson antiadhésif et vaporisez 4 à 5 pressions de spray de cuisson basses calories. Faites rôtir 20 minutes, jusqu'à ce que les bords du chou-fleur commencent à croustiller.","Ajoutez les lentilles, les haricots et le bouillon dans le plat. Mélangez délicatement le tout. Déposez les filets de poisson dessus et poivrez. Faites rôtir 15 à 20 minutes, jusqu'à ce que le poisson s'effeuille.","Incorporez délicatement les oignons nouveaux et l'ail aux lentilles autour des filets de poisson et parsemez de persil. Répartissez dans 4 assiettes et servez avec les quartiers de citron."],
["Découvrez-en plus sur notre partenariat avec Slimming World.",fv(2)]),
R(7802312,"Roulés de tortillas à la dinde et aux canneberges","De petites bouchées aux saveurs classiques des fêtes. Ces roulés peuvent sembler difficiles à réaliser, mais ils se préparent facilement, en très peu de temps et sans effort.","12","50 g",
["4 tortillas complètes (environ 65 g chacune)","110 g de tranches de dinde cuite","75 g de quark allégé","feuilles de 4 brins de thym frais","1 bon tour de moulin de poivre noir","25 g de canneberges séchées","4 feuilles de laitue « little gem », coupées en deux dans la longueur","4 oignons nouveaux fins, parés","½ poivron rouge, coupé en fines lanières","pics à cocktail"],
["Empilez les tortillas et coupez les bords arrondis pour obtenir des tortillas carrées.","Réchauffez les tortillas parées dans une poêle sèche, en les déplaçant pour que chacune soit en contact avec la poêle chaude pendant 1 minute.","Posez les tortillas sur un plan de travail.","En laissant une bordure de 2 cm en haut de chaque tortilla, disposez d'abord les tranches de dinde sur chaque carré, puis étalez le quark allégé et parsemez de thym, de poivre noir et de canneberges. En gardant la bordure du haut, étalez la garniture jusqu'aux bords et jusqu'en bas de chaque carré. Peu importe si la garniture dépasse sur les côtés, vous pourrez la couper une fois roulé.","Disposez la laitue de gauche à droite le long du bord inférieur de chaque tortilla. Au-dessus de la laitue, placez une ligne de lanières de poivron rouge, puis, au-dessus, un oignon nouveau.","Roulez fermement à partir du bas, puis, la jointure sur le dessus, fixez chaque tortilla avec 8 pics à cocktail.","À l'aide d'un couteau bien aiguisé, coupez entre les pics à cocktail pour obtenir 8 roulés, puis disposez-les sur un plat."],
[fv(0)]),
R(7804832,"Curry d'aubergines et de pois chiches","Un délicieux curry végétarien réconfortant, facile à préparer.","4","568 g",
["Spray de cuisson à calories contrôlées","1 oignon rouge, finement émincé","3 gousses d'ail, écrasées","1 c. à soupe de gingembre frais râpé","1/2 c. à soupe de coriandre moulue","3 gousses de cardamome, écrasées","1 anis étoilé","1 c. à soupe de concentré de tomate","2 aubergines, coupées en morceaux de 3 cm","500 g de coulis de tomate (passata)","300 ml de bouillon de légumes, préparé avec 1/2 cube de bouillon à teneur réduite en sel","2 boîtes de 400 g de pois chiches, égouttés et rincés","50 g de yaourt nature sans matières grasses, plus 2 c. à soupe pour servir","Zeste finement râpé et jus d'un demi-citron vert, plus des quartiers pour servir","2 c. à soupe de coriandre fraîche finement hachée, plus un peu pour servir","2 sachets de 250 g de riz basmati complet à cuire au micro-ondes"],
["Vaporisez une grande casserole de spray de cuisson et faites revenir l'oignon à feu moyen 6 à 8 minutes, jusqu'à ce qu'il soit tendre. Ajoutez l'ail et le gingembre, faites cuire 1 minute, incorporez les épices et faites cuire encore 1 minute.","Incorporez le concentré de tomate et faites cuire 1 minute, puis ajoutez les aubergines, le coulis de tomate et le bouillon. Portez à frémissement et laissez cuire 25 minutes, en ajoutant les pois chiches pendant les 5 dernières minutes. Incorporez le yaourt, le zeste et le jus de citron vert, et la coriandre.","Répartissez le riz cuit dans les bols, nappez de curry et de yaourt supplémentaire, parsemez de coriandre et servez les quartiers de citron vert à part."],
[]),
R(7805110,"Burritos au poulet et aux épinards","Ces burritos sont rassasiants et, accompagnés d'une salade, constituent un déjeuner copieux ou un dîner léger.","2","360 g",
["60 g de riz basmati complet","2 c. à café d'huile de colza","1 oignon, finement haché","1 blanc de poulet (environ 125 g), coupé en lanières","½ poivron vert, haché","½ poivron rouge, haché","2 gousses d'ail, écrasées","1 c. à café de piment en poudre doux (fort si vous préférez)","1 c. à café de cumin moulu","1 c. à café d'origan","150 g d'épinards surgelés, décongelés et bien essorés","2 grandes tortillas nature","1 c. à soupe de fromage frais allégé à l'ail et aux herbes","salade, pour servir"],
["Mettez le riz dans une petite casserole avec 75 ml d'eau bouillante, couvrez et laissez cuire 10 minutes. Laissez reposer à couvert 5 minutes de plus.","Pendant ce temps, versez l'huile dans une casserole, ajoutez l'oignon et faites cuire 3 à 4 minutes.","Ajoutez les lanières de poulet et les poivrons hachés. Remuez 4 minutes, jusqu'à ce que le poulet soit cuit.","Ajoutez l'ail, le piment, le cumin et l'origan. Mélangez encore 1 minute. Incorporez les épinards et le riz cuit. Mélangez bien.","Réchauffez les tortillas dans une poêle sèche ou 30 secondes au micro-ondes. Posez-les sur une planche et étalez le fromage frais au centre de chaque tortilla. Répartissez le mélange de poulet et de riz, puis roulez en rabattant les côtés pour former un paquet bien net. Enroulez fermement le paquet dans du papier aluminium, en tordant les extrémités pour le tenir facilement. Servez avec de la salade."],
["Pour un burrito végétarien, utilisez des champignons à la place du poulet.","Vous pouvez utiliser des lanières de dinde ou de bœuf à la place du poulet.",fv(2)]),
R(7805342,"Salade de pastèque, haricots beurre et feta","Une salade fraîche et colorée, rapide et facile à préparer.","4","179 g",
["300 g de chair de pastèque (sans l'écorce)","100 g de roquette","5 à 6 brins de menthe, feuilles déchirées","2 c. à café d'huile d'olive","1 boîte de 400 g de haricots beurre, égouttés","40 g de feta","jus d'un demi-citron","1 bon tour de moulin de poivre noir"],
["Coupez la pastèque en petites tranches et réservez.","Parsemez un plat de service de roquette et de feuilles de menthe et arrosez d'huile d'olive. Disposez la pastèque sur les feuilles, puis répartissez les haricots beurre et la feta dessus.","Arrosez de jus de citron et poivrez pour servir."],
[fv(1)]),
R(7805746,"Pâtes express au saumon","Un excellent plat pour recevoir, qui se déguste aussi très bien froid.","2","382 g",
["2 c. à soupe d'herbes fraîches mélangées, hachées (par ex. persil, coriandre)","zeste râpé et jus d'1 citron vert","2 morceaux de filet de saumon sans peau (environ 100 g chacun)","150 g de pâtes courtes","100 g de pois gourmands","2 tomates, hachées"],
["Mélangez les herbes, le zeste et le jus de citron vert dans un bol non métallique. Ajoutez le saumon et laissez mariner au moins 10 minutes.","Pendant ce temps, faites cuire les pâtes selon les instructions de l'emballage, en ajoutant les pois gourmands 2 minutes avant la fin de la cuisson. Égouttez.","Pendant ce temps, chauffez une poêle épaisse ou une plaque à griller. Lorsqu'elle est chaude, ajoutez le saumon et faites cuire 3 minutes de chaque côté, jusqu'à ce qu'il soit bien cuit à cœur.","Mélangez les pâtes, les pois gourmands, les tomates et le reste de la marinade.","Effeuillez délicatement le saumon et incorporez-le aux pâtes."],
["Vous pouvez utiliser du cabillaud, de l'églefin ou des crevettes tigrées à la place du saumon.","Essayez 2 c. à soupe d'aneth frais haché à la place du persil et utilisez du citron à la place du citron vert.",fv(1)]),
R(7806347,"Lotte marinée","Ce plat épicé regorge de saveurs et est étonnamment pauvre en matières grasses.","4","325 g",
["4 morceaux de lotte fraîche, sans peau (600 g)","zeste et jus d'1 citron vert","2 c. à soupe de sauce soja à teneur réduite en sel","1 pincée de flocons de piment","225 g (poids sec) de riz basmati","1 cube de bouillon de légumes","1 carotte, râpée","30 g de raisins secs blonds","5 feuilles de basilic frais, hachées","poivre noir fraîchement moulu","coriandre fraîche, pour la garniture"],
["Placez la lotte dans un plat peu profond. Mélangez le citron vert, la sauce soja et les flocons de piment, versez sur le poisson et laissez mariner 20 minutes.","Pendant ce temps, faites cuire le riz basmati dans une casserole d'eau bouillante avec un cube de bouillon de légumes. Égouttez et mettez dans un grand saladier. Ajoutez la carotte, les raisins secs et le basilic haché, mélangez bien et gardez au chaud.","Préchauffez le gril à puissance maximale. Placez la lotte sur une plaque de cuisson et poivrez. Faites cuire sous le gril chaud 2 à 3 minutes de chaque côté.","Disposez sur le riz parfumé."],
["Vous pouvez aussi utiliser des steaks de thon ou de saumon à la place de la lotte.","Pour une version végétarienne, faites mariner des cubes de tofu et enfilez-les sur des brochettes avec de l'oignon rouge avant de les faire griller 10 minutes, en les retournant plusieurs fois.",fv(0)]),
R(7809105,"Charlotte aux pommes","Une version plus saine d'un dessert classique, qui associe pommes parfumées et pain pour un dessert réconfortant d'automne.","4","180 g",
["3 pommes non épluchées, évidées et râpées","200 ml de jus de pomme","2 c. à café de cannelle","1 trait d'huile de tournesol","4 à 5 tranches de pain complet, croûtes retirées","1 jaune d'œuf, légèrement battu"],
["Préchauffez le four à 180 °C (th. 4). Mettez les pommes dans une casserole avec 100 ml de jus de pomme et laissez mijoter jusqu'à ce qu'elles soient tendres (4 à 5 minutes). Retirez les pommes en laissant le jus, et placez-les dans un bol.","Ajoutez la cannelle dans la casserole avec les 100 ml de jus de pomme restants et faites fondre doucement, en ajoutant un peu de jus si nécessaire. Laissez refroidir : vous devriez obtenir environ 100 ml de sirop.","Huilez avec l'huile de tournesol l'intérieur d'un petit moule à pudding ou d'un plat allant au four. Trempez le pain dans le sirop de pomme et utilisez-le pour en tapisser le moule. Veillez à ne laisser aucun espace.","Incorporez le jaune d'œuf aux pommes, puis versez le mélange dans le moule tapissé de pain.","Pour finir, recouvrez de pain imbibé de sirop et versez le reste du liquide à la cuillère. Faites cuire 20 minutes. Vérifiez après 15 minutes et, si le dessus est très brun sur les bords, couvrez-le d'une feuille d'aluminium pendant les 5 dernières minutes.","Laissez reposer quelques minutes, décollez les bords avec un couteau et démoulez délicatement sur un plat de service."],
["À déguster de préférence juste après la cuisson.","Essayez de servir avec un peu de yaourt allégé ou de crème fraîche à 15 % de matières grasses.",fv(1)]),
R(7809362,"Gâteau aux poires et aux amandes","Des quartiers de poires cuits dans un gâteau moelleux aux amandes, parsemé d'amandes effilées, pour un délicieux dessert.","12","60 g",
["3 poires, épluchées et coupées en quatre","2 œufs moyens","75 g de sucre en poudre (en réserver 1 c. à café pour le dessus)","100 ml d'huile de colza (en réserver 1 c. à café pour graisser)","1 c. à café d'arôme d'amande","100 g de farine complète","1 c. à café de levure chimique","20 g d'amandes effilées"],
["Préchauffez le four à 180 °C (th. 4) et graissez légèrement une plaque de cuisson (environ 20 cm x 25 cm) avec 1 c. à café d'huile de colza.","Dans un saladier, battez ensemble les œufs, le sucre, l'huile de colza et l'arôme d'amande.","Ajoutez la farine et la levure, mélangez bien et versez dans la plaque de cuisson.","Disposez les poires dessus, parsemez d'amandes et de la c. à café de sucre réservée. Faites cuire 20 à 22 minutes. Le gâteau est cuit lorsqu'un couteau planté au centre ressort propre."],
["Les poires au sirop conviennent également très bien à cette recette.","Vous pouvez utiliser d'autres fruits comme des pommes, des pêches, des nectarines, des cerises ou des prunes dans ce gâteau.","Essayez d'autres arômes, comme la vanille ou le citron, ou ajoutez du zeste de citron ou d'orange râpé.","Congelez enveloppé dans du papier aluminium ou sulfurisé, dans des sacs de congélation étiquetés, pendant 3 mois maximum."]),
R(7812028,"Brochettes de fruits et sauces à tremper","Égayez les fruits frais avec ces brochettes de fruits colorées, idéales pour que les enfants participent à la préparation.","3","193 g",
["400 g de fruits variés, coupés en tranches","2 c. à soupe de fromage blanc quasiment sans matières grasses","Pour la sauce aux fruits rouges (facultatif)§150 g de fruits rouges (de n'importe quelle sorte)","Pour la sauce aux fruits rouges (facultatif)§édulcorant sans sucre, selon le goût"],
["Enfilez simplement les fruits sur des pics à cocktail ou des brochettes.","Si vous préparez la sauce, mettez les fraises et l'édulcorant dans un blender et mixez jusqu'à obtenir une texture lisse, en ajoutant un peu d'eau si la sauce est trop épaisse.","Versez la sauce aux fruits rouges et le fromage blanc dans des bols séparés et servez-les comme sauces à tremper pour les brochettes."],
["Utilisez un yaourt au soja non sucré à la place du fromage blanc si vous êtes intolérant au lactose ou végétalien.","La sauce aux fruits est facultative, car le mixage des fruits libère leurs sucres naturels et les transforme en sucres libres. Le fruit entier est un choix plus sain : vous préférerez peut-être donc déguster cette recette sans sauce, ou en utiliser seulement une petite quantité.",fv(2)]),
R(7813247,"Espadon rôti et salsa sur lentilles du Puy","Un poisson ferme et délicieux servi avec des lentilles réconfortantes, un plat léger mais nourrissant.","4","338 g",
["Pour les lentilles§250 g de lentilles du Puy","Pour les lentilles§2 gousses d'ail, écrasées","Pour les lentilles§600 ml de bouillon de légumes","Pour les lentilles§4 tomates, grossièrement hachées","Pour les lentilles§1 botte d'oignons nouveaux, hachés","Pour les lentilles§4 morceaux d'espadon de 125 g","Pour les lentilles§1 c. à soupe d'huile","Pour les lentilles§poivre noir, pour assaisonner","Pour la salsa§6 c. à soupe d'herbes fraîches mélangées (par ex. persil, coriandre, menthe)","Pour la salsa§2 c. à soupe de câpres, égouttées","Pour la salsa§4 filets d'anchois","Pour la salsa§zeste râpé et jus d'1 citron","Pour la salsa§2 c. à soupe d'huile d'olive"],
["Préchauffez le four à 220 °C (th. 7).","Mettez les lentilles dans une casserole moyenne avec l'ail et le bouillon, portez à ébullition et laissez mijoter 15 à 20 minutes, jusqu'à ce qu'elles soient tendres. Égouttez l'excès de liquide, puis ajoutez les tomates et les oignons nouveaux et mélangez bien. Assaisonnez.","Pendant ce temps, placez l'espadon sur une plaque de cuisson, arrosez d'huile et assaisonnez. Enfournez et laissez cuire environ 10 minutes, jusqu'à ce qu'il soit croustillant et cuit à cœur.","Pour préparer la salsa, mettez tous ses ingrédients dans un blender ou un robot de cuisine et mixez jusqu'à obtenir un mélange homogène, tout en gardant un peu de texture.","Pour servir, répartissez les lentilles dans les assiettes, déposez dessus un morceau d'espadon, puis nappez de salsa."],
["Les enfants, les femmes enceintes et les femmes qui essaient de tomber enceintes ne doivent pas manger d'espadon, car il contient plus de mercure que les autres poissons. Il est conseillé aux autres adultes de ne pas manger plus d'une portion d'espadon par semaine.",fv(2)]),
R(7814654,"Croustillant d'abricots","Une recette rapide aux ingrédients simples pour un dessert léger et rafraîchissant.","6","102 g",
["2 boîtes de 300 g d'abricots au jus de fruits, égouttés","zeste râpé et jus d'1 grosse orange","Pour la garniture§50 g de flocons d'avoine","Pour la garniture§25 g d'amandes effilées","Pour la garniture§15 g de beurre, fondu","Pour la garniture§1 c. à soupe de graines de sésame","Pour la garniture§1 c. à soupe de miel liquide"],
["Préchauffez le four à 200 °C (th. 6).","Disposez les abricots en une seule couche dans un plat allant au four. Arrosez du zeste et du jus d'orange, puis enfournez et laissez cuire 10 minutes.","Pendant ce temps, mélangez tous les ingrédients de la garniture dans un bol.","Parsemez les abricots de garniture et remettez au four 10 à 12 minutes, jusqu'à ce que le dessus soit doré.","Servez avec un peu de glace ou de crème fraîche allégée."],
["Essayez un mélange de graines de courge et de graines de tournesol à la place des amandes.","Les pêches conviennent très bien à la place des abricots."]),
]
save(2,recs)
